SELECT analytics_order_facts.region, SUM(analytics_order_facts.net_revenue) AS net_revenue FROM analytics_order_facts WHERE analytics_order_facts.year = 2024 AND analytics_order_facts.month = 11 AND analytics_order_facts.channel = 'marketplace' AND analytics_order_facts.customer_segment = 'public' GROUP BY analytics_order_facts.region ORDER BY net_revenue DESC, analytics_order_facts.region ASC LIMIT 5
